function fresh(){return{paceVersion:1,...freshExtras(),mail:{sent:{},page:0,filter:'new'},play:freshPlay(),version:VERSION,food:65,mood:70,sleeping:false,coins:30,seconds:0,recipe:'scarf',theme:'garden',patternId:'',work:false,running:false,lastTick:Date.now(),progress:{},owned:{},custom:{},gifts:[],inventory:{},equipped:{head:null,body:null,wall:null,rug:null,plant:null,lamp:null,shelf:null,display:null},orders:{},patterns:[],made:0}}
const clone=x=>JSON.parse(JSON.stringify(x));
function validNumber(n,min=0,max=1e9){return typeof n==='number'&&Number.isFinite(n)&&n>=min&&n<=max}
function validate(s){if(!s||s.version!==VERSION||!validNumber(s.coins)||!validNumber(s.food,0,100)||!validNumber(s.mood,0,100)||!validNumber(s.seconds)||!validNumber(s.made)||!validNumber(s.lastTick,0,Date.now()+86400000)||!recipes[s.recipe]||!themes[s.theme]||typeof s.running!=='boolean'||typeof s.work!=='boolean'||typeof s.sleeping!=='boolean')throw Error('这份存档格式不正确。');for(const k of ['progress','owned','inventory','orders','equipped','custom'])if(!s[k]||typeof s[k]!=='object'||Array.isArray(s[k]))throw Error('存档缺少 '+k);for(const [k,v]of Object.entries(s.progress))if(!validNumber(v,0,10800))throw Error('进度不正确');for(const k of ['owned','inventory'])for(const [id,n]of Object.entries(s[k]))if(!Number.isInteger(n)||!validNumber(n,0,1000000))throw Error('数量不正确');if(!Array.isArray(s.gifts)||s.gifts.length>2000||!Array.isArray(s.patterns)||s.patterns.length>24)throw Error('存档内容过大');for(const p of s.patterns)if(!validPattern(p))throw Error('纹样不正确');for(const g of [...s.gifts,...Object.values(s.custom)])if(!g||!recipes[g.r]||!themes[g.c]||!ranks[g.rank]||(g.pattern&&!validPattern(g.pattern)))throw Error('收藏不正确');if(JSON.stringify(s).length>450000)throw Error('存档过大');normalizePlay(s);normalizeMail(s);normalizeExtras(s);if(!s.paceVersion){for(const key in s.progress){const r=key.split('-')[0];if(recipes[r])s.progress[key]=s.progress[key]/(s.made===0?20:oldRecipeSeconds[r])*recipes[r].seconds}s.paceVersion=1;s.running=false;s.play.focus.running=false}return s}
function validPattern(p){return p&&typeof p.id==='string'&&p.id.length<80&&typeof p.name==='string'&&p.name.length<=18&&Array.isArray(p.cells)&&p.cells.length===64&&p.cells.every(c=>c===null||/^#[a-f0-9]{6}$/i.test(c))}
function load(){try{const raw=localStorage.getItem(STORE);if(raw)return validate(JSON.parse(raw))}catch{}const s=fresh();try{const old=JSON.parse(localStorage.getItem('window-cat-v1'));if(old){if(validNumber(old.food,0,100))s.food=old.food;if(validNumber(old.mood,0,100))s.mood=old.mood;s.sleeping=old.sleeping===true}const c=JSON.parse(localStorage.getItem('window-cat-crafts-v1'));if(c){if(validNumber(c.seconds))s.seconds=c.seconds;if(recipes[c.recipe])s.recipe=c.recipe;if(themes[c.channel])s.theme=c.channel;for(const r in recipes)for(const t in themes){const id=r+'-'+t;if(validNumber(c.progress?.[id],0,120))s.progress[id+'-base']=c.progress[id];for(const rank in ranks){const n=c.owned?.[id+'-'+rank]??(rank==='R'?c.owned?.[id]:0);if(Number.isInteger(n)&&n>0){s.owned[id+'-'+rank]=n;s.made+=n}}}}}catch{}return s}
function freshPlay(){return{completed:0,tasks:[],focus:{running:false,duration:1500,remaining:1500,lastTick:Date.now(),result:''}}}
function normalizePlay(s){if(!s.play){s.play=freshPlay();return}const p=s.play,f=p.focus;if(f&&!f.phase)f.phase='work';if(f&&!['work','break'].includes(f.phase))throw Error('专注阶段不正确');if(!Number.isInteger(p.completed)||!validNumber(p.completed,0,1000000)||!Array.isArray(p.tasks)||p.tasks.length>30||!f||typeof f.running!=='boolean'||![60,900,1500,2700].includes(f.duration)||!validNumber(f.remaining,0,Math.max(300,f.duration))||!validNumber(f.lastTick,0,Date.now()+86400000)||typeof f.result!=='string'||f.result.length>200)throw Error('专注存档格式不正确');for(const t of p.tasks)if(typeof t.id!=='string'||typeof t.text!=='string'||t.text.length>80||typeof t.done!=='boolean')throw Error('清单格式不正确');if(f.result.includes('种子')||f.result.includes('植物')||f.result.includes('花园'))f.result='';}
function settleFocus(now=Date.now()){const p=state.play,f=p.focus;if(!f.running)return;const end=f.lastTick+f.remaining*1000;f.remaining=Math.max(0,(end-now)/1000);f.lastTick=now;if(f.remaining>0)return;state.running=false;if(f.phase==='break'){f.running=false;f.phase='work';f.remaining=f.duration;f.result='休息好了，准备好时再开始下一段。'}else{if(f.duration!==60){p.completed++;state.coins+=10}const rest=f.duration===60?10:300;f.phase='break';f.remaining=Math.max(0,rest-(now-end)/1000);f.running=f.remaining>0;f.result=f.duration===60?'体验结束，无奖励。休息 10 秒。':'这一段织好了，毛线币 +10。休息 5 分钟。';if(!f.running){f.phase='work';f.remaining=f.duration;f.result+=' 准备好时再开始下一段。'}}save();renderPlay()}
function renderFocusClock(){const p=state.play,f=p.focus;$('focusTime').textContent=(f.phase==='break'?'休息 ':'')+timeLabel(Math.ceil(f.remaining));$('focusDuration').value=String(f.duration);$('focusDuration').disabled=f.running;$('focusToggle').textContent=f.phase==='break'?(f.running?'暂停休息':'继续休息'):f.running?'暂停这一段':f.remaining>0&&f.remaining<f.duration?'继续这一段专注':'开始这一段专注';$('focusTotals').textContent='完成 '+p.completed+' 段正式专注';$('focusResult').textContent=f.result||'完成正式专注：获得 10 枚毛线币。'}
function renderPlay(){renderFocusClock();renderTodos()}
function renderTodos(){$('todoList').replaceChildren();for(const t of state.play.tasks){const row=document.createElement('div');row.className='todo-row';const label=document.createElement('label'),checkbox=document.createElement('input'),text=document.createElement('span');checkbox.type='checkbox';checkbox.checked=t.done;text.textContent=t.text;label.classList.toggle('done',t.done);checkbox.onchange=()=>{t.done=checkbox.checked;save();renderTodos()};label.append(checkbox,text);const remove=document.createElement('button');remove.className='todo-remove';remove.textContent='移除';remove.setAttribute('aria-label','移除待办：'+t.text);remove.onclick=()=>{state.play.tasks=state.play.tasks.filter(item=>item.id!==t.id);save();renderTodos()};row.append(label,remove);$('todoList').append(row)}if(!state.play.tasks.length){const p=document.createElement('p');p.className='section-note';p.textContent='今天从一件小事开始吧。';$('todoList').append(p)}}
function freshExtras(){return{petName:'小花',bunny:{active:false,leaveAt:0,nextAt:Date.now()+180000,mess:[],chewed:false,visits:0,gifted:false,giftDue:0}}}
function normalizeExtras(s){if(!s.petName)s.petName='小花';if(typeof s.petName!=='string'||[...s.petName].length>12)throw Error('宠物名字不正确');if(!s.bunny)s.bunny=freshExtras().bunny;const b=s.bunny;if(typeof b.active!=='boolean'||typeof b.chewed!=='boolean'||!Array.isArray(b.mess)||b.mess.length>5||!validNumber(b.nextAt,0,Number.MAX_SAFE_INTEGER)||!validNumber(b.leaveAt,0,Number.MAX_SAFE_INTEGER)||!Number.isInteger(b.visits)||b.visits<0)throw Error('兔子来访存档不正确');for(const m of b.mess)if(!validNumber(m.x,30,610)||!validNumber(m.y,280,350))throw Error('兔子残局位置不正确');if(!validNumber(b.giftDue,0,Number.MAX_SAFE_INTEGER))b.giftDue=0}
function visitBunny(now=Date.now()){const b=state.bunny;if(b.active)return;if(b.mess.length||b.chewed){toast('先把上次留下的残局收拾好，兔兔下次再来。');return}b.active=true;b.visits++;b.leaveAt=now+45000;b.nextAt=now+240000+Math.random()*180000;b.mess=[{x:160,y:316},{x:449,y:330},{x:245,y:342}];b.chewed=true;b.gifted=false;const roll=new Uint32Array(1);crypto.getRandomValues(roll);b.giftDue=roll[0]/4294967296<.3?now+30000:0;save();say('咦，垂耳兔又溜进来了……我的围巾呀！');renderBunny()}
function settleBunny(now=Date.now()){const b=state.bunny;let changed=false;if(b.active&&b.giftDue&&!b.gifted&&now>=b.giftDue){const g={r:'sausage',c:'bakery',rank:'SR',at:now,pattern:null};state.owned['sausage-bakery-SR']=(state.owned['sausage-bakery-SR']||0)+1;state.gifts.push(g);b.gifted=true;b.giftDue=0;changed=true;if(!document.hidden)say('兔兔留下了一条腊肠狗围巾……这算是赔礼吗？')}if(b.active&&now>=b.leaveAt){b.active=false;changed=true}if(!b.active&&!document.hidden&&now>=b.nextAt&&!b.mess.length&&!b.chewed){visitBunny(now);return}if(changed){save();renderBunny();renderAlbum()}}
function renderBunny(){const b=state.bunny;$('bunnyStatus').textContent=b.active?'垂耳兔正在串门':b.mess.length||b.chewed?'兔兔离开了，留下一点小残局':'偶尔串门的垂耳白兔';$('cleanMess').textContent='收拾便便'+(b.mess.length?' · '+b.mess.length+' 处':'');$('cleanMess').disabled=!b.mess.length;$('mendScarf').disabled=!b.chewed;$('inviteBunny').disabled=b.active||!!b.mess.length||b.chewed||Date.now()<b.nextAt;$('bunnyNote').textContent=b.chewed?'围巾样布被啃松了，补几针就好；收藏不会丢失。':'每次来访有 30% 概率留下腊肠狗围巾。礼物进篮，不弹窗。';}
function drawBunny(t){const b=state.bunny;for(const m of b.mess){box(m.x,m.y,9,4,'#846544');box(m.x+2,m.y-3,6,4,'#9d7d55');box(m.x+4,m.y-5,3,3,'#b0956c')}if(b.chewed){box(380,313,32,6,'#c28d78');for(let i=0;i<5;i++)box(380+i*7,319+(i%2)*2,1,5,'#c28d78')}if(!b.active)return;const x=reduceMotion.matches?465:110+Math.abs(Math.sin(t/4400))*400,y=303-(reduceMotion.matches?0:Math.floor(t/170)%2*3);rc.save();rc.translate(Math.round(x),y);box(-20,-20,36,22,'#eee8da');box(-16,-24,28,6,'#fbf6eb');box(-12,-43,27,26,'#faf4e9');box(-18,-43,9,31,'#e3d9ce');box(12,-44,9,32,'#e3d9ce');box(-15,-39,3,22,'#dbb4ad');box(15,-39,3,23,'#dbb4ad');box(-6,-31,3,3,'#514943');box(6,-31,3,3,'#514943');box(0,-26,3,3,'#d39f9d');box(-18,-2,12,5,'#f9f1e5');box(7,-2,12,5,'#f9f1e5');box(-26,-15,8,9,'#fbf5eb');rc.restore()}
let lastSpeechAt=Date.now(),nextMurmur=Date.now()+45000;
const murmurs={idle:['今天的阳光，像一团没绕好的毛线。','你忙你的，我把尾巴收好一点。','如果毛线也会做梦，会梦到什么呢？','刚刚听见邮筒响了……也可能是我的肚子。','这里有你坐过的温度。'],knit:['再织一行，再抬头看看你。','这一针有一点歪，不过摸起来很软。','领口要松一点，才装得下一个大大的哈欠。','电视里下雪了，我想换一团暖色的线。','麻花绕来绕去，最后还是会见面的。','这件毛衣的口袋，可以装一颗小小的勇气。'],sleep:['呼……梦里也有一篮毛线。','晚安。明天再把袖子织完。'],bunny:['兔兔看起来很乖。只是看起来。','我数过了，围巾少的那几针一定不是风吹的。','它用腊肠狗围巾道歉的样子，还挺熟练。']};
function murmur(now){if(document.hidden||now<nextMurmur||now-lastSpeechAt<18000)return;const kind=state.bunny.active||state.bunny.chewed?'bunny':state.sleeping?'sleep':state.running?'knit':'idle',lines=murmurs[kind];say(lines[Math.floor(Math.random()*lines.length)]);nextMurmur=now+40000+Math.random()*25000}
function updatePetName(){document.title=state.petName+'的毛线小屋';$('petNameLabel').textContent=state.petName+'的毛线小屋';$('room').setAttribute('aria-label',state.petName+'在像素小屋里活动，编织时坐在电视旁挥动织针');$('giftTitle').textContent=state.petName+'的礼物篮'}

let state=load(),account=null,remoteRevision=null,dirty=false,syncBusy=false,syncBlocked=false,accountReady=false,toastTimer,shopFilter='all',activeTab='shop',saveCounter=0;
function toast(t){$('toast').textContent=t.replaceAll('小花',state.petName);$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500)}
function save(){try{localStorage.setItem(account?'calico-account-'+account.id:STORE,JSON.stringify(state));$('saveStatus').textContent=account?'账号存档 · 待同步':'访客存档 · 已保存在当前浏览器'}catch{$('saveStatus').textContent='浏览器存储不可用，请导出备份'}dirty=true}
function say(t){$('roomSpeech').textContent=t.replaceAll('小花',state.petName);lastSpeechAt=Date.now()}
function signature(){return state.recipe+'-'+state.theme+'-'+(state.patternId||'base')}
function duration(){return recipes[state.recipe].seconds}
function currentPattern(){return state.patterns.find(p=>p.id===state.patternId)||null}
function randomRank(){const a=new Uint32Array(1);crypto.getRandomValues(a);const n=a[0]/4294967296;return n<.7?'R':n<.95?'SR':'SSR'}
function finishOne(){const r=state.recipe,c=state.theme,rank=randomRank(),p=currentPattern(),id=r+'-'+c+'-'+rank,gift={r,c,rank,reward:craftReward(r,rank),at:Date.now(),pattern:p?clone(p):null};if(p){const customId=id+'-'+p.id;gift.customId=customId;state.custom[customId]={...gift,count:(state.custom[customId]?.count||0)+1}}else state.owned[id]=(state.owned[id]||0)+1;state.gifts.push(gift);state.coins+=gift.reward;state.made++;state.mood=Math.min(100,state.mood+3);for(const o of orderDefs)if(o.recipe===r&&o.theme===c&&state.orders[o.id]==='accepted')state.orders[o.id]='ready';return gift}
function settle(now=Date.now()){const f=state.play.focus;const until=f.running&&f.phase!=='break'?Math.min(now,f.lastTick+f.remaining*1000):now;const count=settleKnitting(until);settleFocus(now);state.lastTick=now;return count}
function settleKnitting(now){settleBunny(now);murmur(now);settleLetters(now);const previous=state.lastTick;state.lastTick=now;if(!state.running||state.sleeping)return 0;let seconds=Math.max(0,(now-previous)/1000);if(state.work)seconds=Math.min(seconds,8*3600);else if(document.hidden||seconds>3)return 0;let count=0;const id=signature();while(seconds>0&&state.running){const remaining=Math.max(0,duration()-(state.progress[id]||0));const used=Math.min(seconds,remaining);state.progress[id]=(state.progress[id]||0)+used;state.seconds+=used;seconds-=used;if(state.progress[id]>=duration()-.00001){state.progress[id]=0;finishOne();count++;if(!state.work||recipes[state.recipe].quick)state.running=false;if(count>=480)break}else break}if(count){save();renderLists();if(!document.hidden)say('小花把 '+count+' 份新礼物放进了篮子，忙完再看吧。')}return count}
function pause(){settle();state.play.focus.running=false;state.running=false;state.lastTick=Date.now();save();render()}
function selectedSetup(){state.recipe=$('recipe').value;state.theme=$('channel').value;state.patternId=$('patternChoice').value;save();render()}
$('focusDuration').onchange=()=>{settleFocus();const f=state.play.focus;state.running=false;f.phase='work';f.duration=Number($('focusDuration').value);f.remaining=f.duration;f.running=false;f.lastTick=Date.now();f.result='';save();renderFocusClock()};
$('focusToggle').onclick=()=>{if(recipes[state.recipe].quick){toast('袜子和小包用于快速看纹样；正式专注请选择围巾、帽子或毛衣。');return}settle();const f=state.play.focus;if(f.running){f.running=false;state.running=false;save();render();return}if(f.phase==='break'){f.running=true;f.lastTick=Date.now();save();render();return}if(state.sleeping){toast('先轻轻叫醒小花，再开始一起专注。');return}if(activity==='eat'){toast('小花吃完这口就来。');return}if(f.remaining<=0)f.remaining=f.duration;f.running=true;f.lastTick=Date.now();f.result='';state.work=true;state.running=true;state.lastTick=Date.now();save();render();say('这一段，我织毛线，你做自己的事。完成后奖励会安静收好。')};
$('todoForm').onsubmit=e=>{e.preventDefault();const text=$('todoInput').value.trim();if(!text)return;if(state.play.tasks.length>=30){toast('先收拾一下清单吧，最多保留 30 件小事。');return}state.play.tasks.push({id:'t'+Date.now().toString(36)+Math.random().toString(36).slice(2,5),text,done:false});$('todoInput').value='';save();renderTodos()};
$('cleanMess').onclick=()=>{if(!state.bunny.mess.length)return;state.bunny.mess=[];state.mood=Math.min(100,state.mood+3);save();render();say('收拾好了。下次要在门口放个兔兔厕所。')};
$('mendScarf').onclick=()=>{if(!state.bunny.chewed)return;state.bunny.chewed=false;state.mood=Math.min(100,state.mood+3);save();render();say('松掉的几针补好了，围巾还是暖暖的。')};
$('inviteBunny').onclick=()=>{if(Date.now()<state.bunny.nextAt)return;visitBunny()};
$('renamePet').onclick=()=>{$('petNameInput').value=state.petName;$('nameError').textContent='';$('nameDialog').showModal();$('petNameInput').focus()};$('cancelName').onclick=()=>$('nameDialog').close();
$('nameForm').onsubmit=e=>{e.preventDefault();const name=$('petNameInput').value.trim();if(!name||[...name].length>12){$('nameError').textContent='请输入 1～12 个字的名字。';return}state.petName=name;save();render();say('以后就叫我'+name+'啦。这个名字软软的，我喜欢。');$('nameDialog').close()};
$('recipe').onchange=selectedSetup;$('channel').onchange=selectedSetup;$('patternChoice').onchange=selectedSetup;
$('workMode').onchange=()=>{settle();state.work=$('workMode').checked;state.lastTick=Date.now();save();render()};
$('knit').onclick=()=>{if(!recipes[state.recipe].quick){$('focusToggle').click();return}if(state.running){pause();return}if(state.sleeping||activity==='eat'){toast('等猫猫醒来、吃好再织小样吧。');return}settle();state.play.focus.running=false;state.running=true;state.work=true;state.lastTick=Date.now();save();render();say('先织一件小作品看看纹样，织好就收进篮子。')};
$('pat').onclick=()=>{if(state.sleeping){say('嘘，小花正做着毛线球的梦。');return}state.mood=Math.min(100,state.mood+8);heartUntil=performance.now()+1600;save();render();say('呼噜呼噜……小花蹭了蹭你的手。')};
$('feed').onclick=()=>feedCat(20,2,'日常猫粮');
function feedCat(food,mood,name){if(state.sleeping){toast('小花睡着了，叫醒后再吃吧。');return false}if(state.food>=100){toast('已经吃饱啦，这份先留着。');return false}pause();state.food=Math.min(100,state.food+food);state.mood=Math.min(100,state.mood+mood);activity='eat';catTarget=78;activityEnd=performance.now()+5000;save();render();say('啊呜，'+name+'真好吃。');return true}
$('sleep').onclick=()=>{pause();state.sleeping=!state.sleeping;activity=state.sleeping?'sleep':'idle';catTarget=state.sleeping?555:320;save();render();say(state.sleeping?'睡一觉，醒来再织。':'伸个懒腰，又能陪你啦。')};
function timeLabel(n){n=Math.floor(n);const h=Math.floor(n/3600);return(h?h+':':'')+String(Math.floor(n/60)%60).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}
function render(){updatePetName();renderBunny();renderFocusClock();renderKnitPreview();$('removeDisplay').hidden=!state.equipped.display;for(const k of ['food','mood']){$(k).value=state[k];$(k+'Text').textContent=Math.round(state[k])}$('coins').textContent=state.coins;$('made').textContent=state.made;$('companionTime').textContent=timeLabel(state.seconds);$('basketCount').textContent=state.gifts.length;$('workMode').checked=state.work;$('recipe').value=state.recipe;$('channel').value=state.theme;$('patternChoice').value=state.patternId;for(const id of ['recipe','channel','patternChoice'])$(id).disabled=state.running;const pct=Math.min(100,(state.progress[signature()]||0)/duration()*100);$('knitProgress').value=pct;$('progressText').textContent=Math.floor(pct)+'%';$('currentProject').textContent=themes[state.theme].prefix+recipes[state.recipe].name+(currentPattern()?' · 自绘':'');$('knitStatus').textContent=(state.running?(state.work?'工作陪伴中':'安静编织中'):'已暂停')+' · 本件剩余 '+Math.ceil(duration()*(1-pct/100)/60)+' 分钟 · 约 '+Math.ceil(duration()/1500)+' 段标准番茄钟';$('knit').textContent=state.play.focus.phase==='break'?'休息中 · 点击暂停或继续':state.running?'暂停这一段，保留进度':'开始 / 继续一段专注';if(recipes[state.recipe].quick){$('knitStatus').textContent=(state.running?'快速编织中':'快速作品')+' · 剩余 '+Math.ceil(duration()*(1-pct/100))+' 秒 · 织一件后停下';$('knit').textContent=state.running?'暂停，保留小样进度':'织一件小作品 · '+recipes[state.recipe].seconds+' 秒'}$('rewardPreview').textContent=recipes[state.recipe].quick?'纹样试织：不发毛线币，不计专注奖励；成品照常收藏。':'本件完成奖励：R '+craftReward(state.recipe,'R')+' / SR '+craftReward(state.recipe,'SR')+' / SSR '+craftReward(state.recipe,'SSR')+' ◈';$('sleep').textContent=state.sleeping?'☀ 轻轻叫醒':'☾ 睡一会儿';$('catState').textContent=state.sleeping?'● 休息中':state.running?'● 边看边织':'● 自由活动';$('roomClock').textContent=new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});$('collectionCount').textContent=Object.keys(state.owned).filter(k=>state.owned[k]>0).length+' / '+(Object.values(recipes).filter(r=>!r.giftOnly).length*12+1);}
function productArt(g){const c=document.createElement('canvas');c.width=40;c.height=32;const x=c.getContext('2d');const rect=(a,b,w,h,color)=>{x.fillStyle=color;x.fillRect(a,b,w,h)};const ink='#6c5944';if(g.id==='christmasTree'){rect(18,24,5,6,ink);for(let i=0;i<4;i++)rect(18-i*3,6+i*5,5+i*6,6,'#527957');rect(19,2,3,5,'#efcc70');rect(13,17,3,3,'#c47459');rect(24,22,3,3,'#efcc70');rect(5,26,9,6,'#b95546');return c}if(g.id==='christmasLights'){rect(7,8,26,2,ink);for(let i=8;i<33;i+=6)rect(i,10,3,4,i%2?'#b95546':'#e5bd65');rect(14,17,14,12,'#527957');rect(18,20,6,6,'#eee2c8');rect(18,17,5,3,'#b95546');return c}if(g.theme){const p=furnitureThemes[g.theme];rect(5,8,30,20,p.wood);rect(7,10,26,15,p.light);if(g.slot==='window'){rect(13,9,14,16,'#add1cf');rect(19,9,2,16,p.trim);rect(13,16,14,2,p.trim);rect(6,7,6,20,p.cloth);rect(28,7,6,20,p.cloth)}else if(g.slot==='tv'){rect(9,3,22,16,ink);rect(11,5,18,12,'#839d98');rect(8,24,24,2,p.trim)}else if(g.slot==='bed'){rect(8,12,24,12,p.cloth);rect(12,14,16,8,p.trim)}else if(g.slot==='desk'){rect(8,27,3,4,ink);rect(29,27,3,4,ink);rect(10,4,12,5,p.trim);rect(25,2,5,7,p.cloth)}else{rect(7,17,26,2,ink);for(let a=10;a<30;a+=7){rect(a,11,5,5,p.cloth);rect(a,21,5,4,p.trim)}}return c}if(g.type==='wear'){if(g.id==='bow'){rect(8,11,10,9,g.color);rect(22,11,10,9,g.color);rect(17,13,6,5,'#eed3c4');rect(10,12,3,3,'#ecc4c2')}else if(g.id==='beret'){rect(8,13,25,9,g.color);rect(12,9,17,5,g.color);rect(22,6,3,5,ink);rect(8,21,25,3,ink);rect(13,12,11,2,'#d9ae7b')}else{rect(12,6,16,19,g.color);rect(8,9,24,8,g.color);rect(14,7,12,3,'#e5d6ad');rect(17,15,6,7,'#ddcfaa');rect(12,25,16,2,ink)}}else if(g.type==='food'){if(g.id==='fish'){rect(7,17,27,6,'#c0c5b1');rect(12,12,15,8,g.color);rect(27,10,5,11,g.color);rect(14,14,2,2,ink);rect(16,15,8,1,'#d7e2d4')}else{rect(10,22,23,3,'#a7b5b4');rect(13,12,17,11,g.color);rect(16,8,11,5,g.color);rect(15,12,13,3,'#b97e50');rect(20,5,4,4,'#c37569')}}else if(g.slot==='wall'){rect(8,5,24,23,g.color);for(let a=10;a<32;a+=6)rect(a,5,1,23,'#ffffff55');rect(8,26,24,3,ink)}else if(g.slot==='rug'){rect(5,8,30,19,g.color);rect(8,11,24,13,'#d4d6b3');rect(11,14,18,7,g.color);for(let a=6;a<35;a+=4){rect(a,5,1,3,ink);rect(a,27,1,3,ink)}}else if(g.slot==='plant'){rect(15,19,13,10,'#b8805e');rect(20,7,3,14,'#67835d');rect(12,9,8,5,g.color);rect(23,4,8,6,g.color);rect(17,1,6,8,g.color)}else if(g.slot==='lamp'){rect(19,12,3,15,ink);rect(13,26,16,3,ink);rect(12,7,18,8,g.color);rect(15,4,12,4,g.color);rect(13,14,16,2,'#fff1bc')}else{rect(7,4,26,25,ink);rect(9,6,22,21,'#cba879');rect(9,15,22,3,ink);for(let a=11;a<30;a+=6)rect(a,8,4,7,['#8fa486','#c58c76','#9aacb8'][Math.floor(a/6)%3])}return c}
function switchTab(name){activeTab=name;for(const b of document.querySelectorAll('[data-tab]')){const on=b.dataset.tab===name;b.classList.toggle('selected',on);b.setAttribute('aria-selected',String(on))}for(const n of ['shop','album','closet','patterns','focus'])$(n+'Panel').hidden=n!==name;if(name==='patterns')paintEditor();if(name==='focus')renderPlay()}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));
document.querySelectorAll('[data-shop]').forEach(b=>b.onclick=()=>{shopFilter=b.dataset.shop;document.querySelectorAll('[data-shop]').forEach(el=>el.classList.toggle('selected',el===b));renderShop()});
function buy(id){const g=byGood[id];if(!g)return;if(g.type!=='food'&&state.inventory[id]){equip(id);return}if(state.coins<g.price){toast('毛线币还差 '+(g.price-state.coins)+' 枚，织点小礼物就能攒到。');return}state.coins-=g.price;state.inventory[id]=(state.inventory[id]||0)+1;if(g.type!=='food')state.equipped[g.slot]={source:'shop',id};save();render();renderLists();toast(g.type==='food'?g.name+'已放进背包。':'换上了'+g.name+'，小屋又温暖了一点。')}
function equip(id){const g=byGood[id];if(!g||!state.inventory[id])return;if(g.type==='food'){if(!feedCat(g.food,g.mood,g.name))return;state.inventory[id]--}else{const current=state.equipped[g.slot];state.equipped[g.slot]=current?.id===id?null:{source:'shop',id}}save();render();renderLists()}
