function sweaterMask(type,x,y){let body=y>=8&&y<=21&&x>=6&&x<=17;let sleeves=y>=6&&y<=15&&((x>=1&&x<=5)||(x>=18&&x<=22));if(type==='vest')sleeves=false;if(y>=5&&y<=9&&x>=4&&x<=19)body=true;if(type==='vest'&&y>=5&&y<=9&&(x<6||x>17))body=false;if(y<9&&x>=10&&x<=13)body=false;if(type==='cardigan'&&y<12&&Math.abs(x-11.5)<(12-y)*.5)body=false;if(type==='hoodie'&&y>=1&&y<=6&&x>=8&&x<=15)body=true;return body||sleeves}
