function stitchColor(g,x,y){const theme=themes[g.c];let color=g.r==='sausage'?'#a76d43':theme.color;if(g.r==='sausage'&&x===2&&y===4)return '#423c34';if(g.r==='crew'&&Math.floor(y/3)%2)color=theme.accent;else if(g.r==='cable'&&((x===9||x===14)&&y%4<2||(x===10||x===13)&&y%4>=2))color='#e6d3ac';else if(g.r==='vest'&&(Math.abs(x%8-4)+Math.abs(y%8-4)===4))color=theme.accent;else if(g.rank==='SR'&&(x+y)%7===0)color='#e9d8b1';if(g.rank==='SSR'&&(x+y)%9===0)color='#edd17d';if(y===20||y===21)color=theme.accent;if(g.pattern){const p=g.pattern.cells[(y%8)*8+x%8];if(p)color=p}return color}
function drawItem(canvas,g,fraction=1){canvas.width=96;canvas.height=96;const ctx=canvas.getContext('2d');ctx.clearRect(0,0,96,96);const sweater=['crew','cable','cardigan','vest','hoodie'].includes(g.r),grid=sweater?24:16,unit=96/grid;const fromRow=Math.floor((1-Math.max(0,Math.min(1,fraction)))*grid);for(let y=fromRow;y<grid;y++)for(let x=0;x<grid;x++){const visible=sweater?sweaterMask(g.r,x,y):g.r==='sausage'?((y>=6&&y<=9&&x>=2&&x<=13)||(x>=1&&x<=4&&y>=3&&y<=7)||(y>=10&&y<=12&&(x===4||x===11))||(x===14&&y>=4&&y<=6)):silhouettes[g.r]?.[y]?.[x]==='X';if(!visible)continue;const px=x*unit,py=y*unit;ctx.fillStyle=stitchColor(g,x,y);ctx.fillRect(px,py,unit,unit);ctx.fillStyle='#f9eac544';ctx.fillRect(px+1,py+1,1,1);ctx.fillRect(px+unit-2,py+1,1,1);ctx.fillStyle='#503d3025';ctx.fillRect(px+unit/2,py+unit-2,1,1);if(sweater&&(y>=20||(!sweaterMask(g.r,x,y-1)&&y>4))){ctx.fillStyle='#f5dec177';ctx.fillRect(px+1,py,1,unit)}if(g.r==='cardigan'&&y>=10&&y<21&&x===12){ctx.fillStyle='#decb9c';ctx.fillRect(px,py,2,unit);if(y%3===1){ctx.fillStyle='#66503a';ctx.fillRect(px+1,py+1,2,2)}}if(g.r==='hoodie'&&y>=14&&y<=18&&x>=9&&x<=14){ctx.fillStyle='#e3cda955';ctx.fillRect(px,py,unit,unit)}}}
function renderKnitPreview(){const progress=(state.progress[signature()]||0)/duration(),g={r:state.recipe,c:state.theme,rank:'R',pattern:currentPattern()},canvas=$('workPreview');drawItem(canvas,g);const ctx=canvas.getContext('2d');ctx.fillStyle='#faf5e8cc';ctx.fillRect(0,0,96,96);const partial=document.createElement('canvas');drawItem(partial,g,progress);ctx.drawImage(partial,0,0);const y=Math.max(4,Math.min(91,96*(1-progress)));ctx.strokeStyle='#8e7454';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(12,y-3);ctx.lineTo(84,y+3);ctx.moveTo(82,y-4);ctx.lineTo(14,y+4);ctx.stroke();const stages=recipes[state.recipe].quick?(state.recipe==='socks'?['起针，织袜口','织出袜筒','转过袜跟','收好袜尖']:['起针，织包底','织出包身纹样','收好包口','接上小提手']):['起针，织出罗纹边','一行一行织衣身','整理袖片与边缘','收好领口，缝合完成'];$('knitStage').textContent=progress===0?'准备起针':stages[Math.min(3,Math.floor(progress*4))];$('knitRows').textContent=Math.floor(progress*24)+' / 24 行 · '+recipes[state.recipe].name;$('knitTechnique').textContent=recipes[state.recipe].quick?'快速看纹样，完成后到礼物篮和图鉴查看。':state.recipe==='cable'?'交错麻花纹，带一点软软的厚度。':state.recipe==='cardigan'?'V 领、门襟和一排小纽扣。':state.recipe==='vest'?'轻便无袖，菱格花纹。':state.recipe==='hoodie'?'连着帽子，还有暖手的小口袋。':state.recipe==='crew'?'圆领、条纹和细细的罗纹袖口。':'每一行都能看见针织纹理。'}
function collectionEntries(){const a=[];for(const r in recipes)for(const c in themes)for(const rank in ranks){if(recipes[r].giftOnly&&(c!=='bakery'||rank!=='SR'))continue;const id=r+'-'+c+'-'+rank;a.push({id,r,c,rank,count:state.owned[id]||0})}for(const [id,g]of Object.entries(state.custom))a.push({...g,id,customId:id,count:g.count||0});return a}
