function wearGift(g,slot){if(g.count<1)return;if(slot==='display'&&state.equipped.display?.id===g.id){removeDisplay();return}if(slot!=='display'&&state.equipped[slot]?.source==='craft'&&state.equipped[slot]?.id===g.id){state.equipped[slot]=null;save();render();renderAlbum();toast('手作已经脱下，仍然保留在图鉴里。');return}state.equipped[slot]={source:'craft',r:g.r,c:g.c,rank:g.rank,pattern:g.pattern||null,id:g.id};save();render();renderAlbum();toast(slot==='display'?'把作品挂到了房间里。':'小花换上了你的手作。')}
