function normalizeMail(s){if(!s.mail)s.mail={sent:{},page:0,filter:'new'};if(!s.mail.sent||typeof s.mail.sent!=='object'||!Number.isInteger(s.mail.page)||s.mail.page<0||!['new','active','done'].includes(s.mail.filter))throw Error('信箱存档格式不正确');for(const v of Object.values(s.mail.sent))if(!validNumber(v,0,Date.now()+86400000))throw Error('寄信日期不正确')}
function settleLetters(now){let changed=false;for(const o of orderDefs)if(state.orders[o.id]==='sent'&&now>=state.mail.sent[o.id]){state.orders[o.id]='arrived';changed=true}if(changed){save();renderOrders()}}
function filteredLetters(){return orderDefs.filter(o=>{const status=state.orders[o.id];if(state.mail.filter==='done')return status==='claimed';if(state.mail.filter==='active')return ['accepted','ready','sent','arrived'].includes(status);return !status&&(!o.requires||state.orders[o.requires]==='claimed')})}
function acceptLetter(o){const status=state.orders[o.id];if(status==='ready'){state.orders[o.id]='sent';state.mail.sent[o.id]=Date.now()+o.delay*1000;toast('已经寄出，'+o.delay+' 秒左右会收到回信。');save();renderOrders();return}if(status==='arrived'){state.orders[o.id]='claimed';state.coins+=o.coins;save();render();renderOrders();toast('收到 '+o.from+' 的明信片和 '+o.coins+' 枚毛线币。');return}if(status==='sent'||status==='claimed')return;if(!status&&orderDefs.filter(x=>['accepted','ready','sent','arrived'].includes(state.orders[x.id])).length>=3){toast('最多同时往来三封信，先给手头的朋友回信吧。');return}if(!status)state.orders[o.id]='accepted';if(state.running)pause();state.recipe=o.recipe;state.theme=o.theme;state.patternId='';state.mail.filter='active';state.mail.page=0;save();render();renderOrders();say('选好了「'+o.title+'」的配方。点开始，替远方的朋友织一件。');$('knit').focus()}
function stampCanvas(o){const c=document.createElement('canvas');c.width=96;c.height=48;const g=c.getContext('2d');const r=(x,y,w,h,color)=>{g.fillStyle=color;g.fillRect(x,y,w,h)};const sky=o.place==='月桥'?'#8999b5':o.place==='雪山'?'#b2c8cc':'#c7d6c0';r(0,0,96,48,sky);r(73,7,9,9,'#f5dfa0');r(0,35,96,13,'#91a78a');if(o.place==='海边'||o.place==='月桥'){r(0,30,96,18,'#839fae');for(let x=3;x<96;x+=15)r(x,36,9,1,'#c7d8d2');if(o.place==='月桥'){r(19,24,61,4,'#dbc9a1');r(21,28,4,10,'#ad9672');r(73,28,4,10,'#ad9672')}else{r(21,11,8,24,'#f0e0bb');r(19,10,12,4,'#bc8571')}}else if(o.place==='森林'){for(let i=4;i<90;i+=19){r(i+5,17,4,21,'#8a7756');r(i,21,16,9,'#789471');r(i+3,15,10,8,'#8fa780')}}else if(o.place==='雪山'){for(let i=0;i<3;i++){for(let y=0;y<22;y++)r(i*29+15-y/2,13+y,4+y,1,y<7?'#f4efe1':'#9caaa5')}}else if(o.place==='列车'){r(4,22,84,16,'#b98467');r(8,25,74,6,'#e8d9af');for(let i=15;i<85;i+=18)r(i,25,2,6,'#9a7658');r(12,38,8,4,'#5b5a50');r(70,38,8,4,'#5b5a50')}else{for(let i=5;i<92;i+=22){r(i,20,17,17,'#e0c6a0');r(i-2,17,21,5,'#ae836c');r(i+4,25,5,6,'#8fa5a2')}}return c}
function renderOrders(){$('mailFilter').value=state.mail.filter;$('orders').replaceChildren();$('postcards').replaceChildren();const all=filteredLetters(),pages=Math.max(1,Math.ceil(all.length/3));state.mail.page=Math.min(state.mail.page,pages-1);$('mailPage').textContent=(state.mail.page+1)+' / '+pages;$('mailPrev').disabled=state.mail.page===0;$('mailNext').disabled=state.mail.page>=pages-1;for(const o of all.slice(state.mail.page*3,state.mail.page*3+3)){const status=state.orders[o.id],box=document.createElement('article');box.className='order letter';box.append(stampCanvas(o));const sender=document.createElement('small');sender.textContent=o.from;const title=document.createElement('strong');title.textContent=o.title;const story=document.createElement('p');story.textContent=o.request;const needs=document.createElement('p');needs.className='letter-needs';needs.textContent=themes[o.theme].prefix+recipes[o.recipe].name+' · 回礼 '+o.coins+' ◈';const b=document.createElement('button');b.textContent=status==='accepted'?'继续这份编织':status==='ready'?'打包寄出':status==='sent'?'在路上 · 等待回信':status==='arrived'?'拆开回信，领取回礼':status==='claimed'?'明信片已收好':'接下这封来信';b.disabled=status==='sent'||status==='claimed';b.onclick=()=>acceptLetter(o);box.append(sender,title,story,needs,b);$('orders').append(box)}if(!all.length){const p=document.createElement('p');p.className='section-note';p.textContent=state.mail.filter==='active'?'暂时没有往来的信，去看看新来信吧。':state.mail.filter==='done'?'第一封明信片还在路上。':'这一批信都接过啦。新的故事会从回信里继续。';$('orders').append(p)}for(const o of orderDefs){if(state.orders[o.id]!=='claimed')continue;const letter=document.createElement('article');letter.className='postcard';letter.append(stampCanvas(o));const h=document.createElement('h3');h.textContent='✉ '+o.title;const body=document.createElement('p');body.textContent=o.body;const from=document.createElement('small');from.textContent=o.from;letter.append(h,body,from);$('postcards').append(letter)}}
