const palette=['#f8f3e8','#fff7d6','#e8d9b5','#d7b56d','#b88b47','#8c623e','#d95b63','#b8424e','#8f2938','#642331','#d79ba2','#edc1c2','#b7c79d','#89a079','#567b5d','#2d5945','#173f34','#a7c9c5','#77a6af','#506f8c','#343f61','#a49bb8','#63556f','#4c443e',null];let paintColor=palette[1],cells=Array(64).fill(null),cursor=0,drawing=false;
function paintEditor(){const c=$('patternCanvas').getContext('2d');for(let i=0;i<64;i++){const x=(i%8)*32,y=Math.floor(i/8)*32;c.fillStyle=cells[i]||((i%8+Math.floor(i/8))%2?'#e9e3d2':'#f7f0df');c.fillRect(x,y,32,32);c.strokeStyle='#bdaf9455';c.strokeRect(x+.5,y+.5,31,31)}if(document.activeElement===$('patternCanvas')){c.strokeStyle='#405e46';c.lineWidth=3;c.strokeRect(cursor%8*32+2,Math.floor(cursor/8)*32+2,28,28);c.lineWidth=1}}
palette.forEach(color=>{const b=document.createElement('button');b.style.background=color||'#faf4e8';b.textContent=color?'':'⌫';b.setAttribute('aria-label',color?'毛线颜色 '+color:'橡皮擦');b.title=color||'橡皮擦';b.classList.toggle('selected',color===paintColor);b.onclick=()=>{paintColor=color;[...$('palette').children].forEach(el=>el.classList.toggle('selected',el===b))};$('palette').append(b)});
function paintAt(e){const r=$('patternCanvas').getBoundingClientRect(),x=Math.floor((e.clientX-r.left)/r.width*8),y=Math.floor((e.clientY-r.top)/r.height*8);if(x<0||x>7||y<0||y>7)return;cursor=y*8+x;cells[cursor]=paintColor;paintEditor()}
