$('patternCanvas').onpointerdown=e=>{drawing=true;$('patternCanvas').setPointerCapture(e.pointerId);paintAt(e)};$('patternCanvas').onpointermove=e=>{if(drawing)paintAt(e)};$('patternCanvas').onpointerup=()=>drawing=false;$('patternCanvas').onpointercancel=()=>drawing=false;$('patternCanvas').onfocus=paintEditor;$('patternCanvas').onblur=paintEditor;
