function furniturePalette(slot){return furnitureThemes[byGood[state.equipped[slot]?.id]?.theme]||{wood:'#92704f',light:'#bc986b',cloth:'#bf9555',trim:'#e7d4a5'}}
// Tailored silhouettes share the album's stitch colors, rather than its flat shape.
function wornPatch(g,x,y,w,h,sx=0,sy=0){for(let j=0;j<h;j+=3)for(let i=0;i<w;i+=3){box(x+i,y+j,Math.min(3,w-i),Math.min(3,h-j),stitchColor(g,sx+i/3,sy+j/3));box(x+i+1,y+j+1,1,1,'#fff4d733')}}
function drawWornCraft(g,slot){const edge='#655044',accent=themes[g.c].accent;
if(slot==='head'){wornPatch(g,-23,-75,46,12,1,7);wornPatch(g,-17,-85,34,12,4,3);box(-26,-64,52,4,accent);box(-4,-92,9,7,accent);return}
// The chin ends at row 16 (y=-21); clothing begins below it.
if(g.r==='bag'){
line(-11,-21,20,-9,edge,3);for(let i=0;i<10;i++)box(-12+i*3,-22+Math.floor(i*1.3),3,2,stitchColor(g,i,5));
frameBox(16,-15,15,16,themes[g.c].color,edge,1);wornPatch(g,17,-14,13,13,3,6);box(17,-14,13,4,accent);box(22,-10,3,4,edge);box(23,-10,1,2,'#f2d99a');return}
if(g.r==='scarf'||g.r==='sausage'){
// A narrow collar with a small side knot; the muzzle stays fully visible.
wornPatch(g,-15,-20,27,3,2,0);wornPatch(g,-12,-17,21,2,3,1);box(-10,-15,18,1,'#604a3933');
wornPatch(g,10,-17,6,13,6,4);wornPatch(g,8,-19,9,4,5,2);for(let x=11;x<18;x+=3)box(x,-4,1,3,accent);
if(g.r==='sausage'){box(12,-7,11,5,'#a76d43');box(20,-10,5,6,'#a76d43');box(23,-9,1,1,edge);box(20,-8,2,4,'#70482f');box(13,-2,2,3,'#70482f');box(20,-2,2,3,'#70482f')}return}
// Map garment cells onto the existing torso; never grow sideways human sleeves.
for(let row=17;row<=21;row++)for(let col=5;col<=15;col++){
if(!['W','T'].includes(catPixels[row][col]))continue;
// Front leg openings remain uncovered on sleeveless garments.
if(g.r==='vest'&&row>=19&&(col<=6||col>=14))continue;
const x=-36+col*3,y=-72+row*3;box(x,y,3,3,stitchColor(g,col,row));box(x+1,y+1,1,1,'#fff4d733');if(col===5||col===15)box(x,y,1,3,'#56413333')}
// Neck ribbing sits below the cheeks. Two short cuffs follow downward legs.
box(-15,-22,27,3,accent);box(-12,-22,21,1,'#f8f3e8');
if(g.r!=='vest'){box(-20,-8,9,2,accent);box(3,-8,9,2,accent)}
if(g.r==='cardigan'){line(-12,-20,-3,-16,accent,2);line(9,-20,-3,-16,accent,2);box(-4,-16,2,10,accent);box(-3,-14,1,1,edge);box(-3,-9,1,1,edge)}
if(g.r==='hoodie'){box(-19,-24,5,5,themes[g.c].color);box(12,-24,5,5,themes[g.c].color);box(-11,-18,1,5,accent);box(7,-18,1,5,accent);box(-8,-11,13,4,'#57453533')}
// Restore the original front paws and toes in front of the hem.
for(let row=22;row<24;row++)for(let col=0;col<24;col++){const color=catColors[catPixels[row][col]];if(color)box(-36+col*3,-72+row*3,3,3,color)}
}
