function animate(t){const dt=Math.min(.05,(t-lastFrame)/1000);lastFrame=t;if(!document.hidden){if(state.running){catTarget=320;activity='knit'}else if(state.sleeping){catTarget=555;activity='sleep'}else if(activity==='eat'&&t<activityEnd){catTarget=78}else{if(activity!=='idle')activity='idle';if(t>nextWalk&&!reduceMotion.matches){catTarget=110+Math.random()*420;nextWalk=t+5000+Math.random()*6000}}if(reduceMotion.matches)catX=catTarget;else{const d=catTarget-catX;catX+=Math.sign(d)*Math.min(Math.abs(d),dt*62)}drawRoom(t)}requestAnimationFrame(animate)}
// 免费静态版本：每个浏览器的存档互相独立，无需账号或服务器。
async function initAccount(){accountReady=true;settle();save();renderPatterns();renderLists();render();accountUI()}
function accountUI(){$('accountForm').hidden=true;$('accountActions').hidden=true;$('accountInfo').textContent='免费独立存档：你和朋友打开同一个链接，各自的进度保存在自己的浏览器里。无需注册。换电脑、换浏览器或清理数据前，请先导出备份。';}
async function syncRemote(){}
$('accountOpen').onclick=()=>{accountUI();$('accountDialog').showModal()};$('closeAccount').onclick=()=>$('accountDialog').close();
$('exportSave').onclick=()=>{settle();save();const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='小花存档-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('备份已导出，可在其他电脑导入。')};
let importCandidate=null;$('importSave').onclick=()=>$('importFile').click();$('importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>450000)throw Error('备份文件太大。');importCandidate=validate(JSON.parse(await file.text()));$('importConfirm').hidden=false;$('replaceConfirm').checked=false;$('accountMessage').textContent='已读取备份：'+importCandidate.made+' 件手作，'+importCandidate.coins+' 枚毛线币。确认后会替换当前进度。'}catch(err){importCandidate=null;$('accountMessage').textContent=err.message}e.target.value=''};
$('applyImport').onclick=()=>{if(!importCandidate||!$('replaceConfirm').checked){$('accountMessage').textContent='请勾选确认替换当前进度。';return}state=clone(importCandidate);state.running=false;state.lastTick=Date.now();save();renderPatterns();renderLists();render();syncRemote();importCandidate=null;$('importConfirm').hidden=true;$('accountMessage').textContent='备份已导入。编织已暂停，准备好后可继续。'};
document.addEventListener('visibilitychange',()=>{if(document.hidden){settle();save();syncRemote()}else{settle();render();save();syncRemote()}});window.addEventListener('pagehide',()=>{settle();save();});
